"""Text helpers."""

import re
import unicodedata


def truncate(text, limit):
    """Cut `text` to at most `limit` characters, ending in an ellipsis when it was cut."""
    if limit < 1:
        raise ValueError("limit must be at least 1")
    if len(text) <= limit:
        return text
    return text[: max(limit - 1, 0)] + "…"


def _transliterate_diacritics(text):
    """Replace a character with its ASCII base letter when its Unicode decomposition reduces to exactly one ASCII letter (covers accented Latin letters and similar compatibility forms), leaving any other character unchanged."""
    result = []
    for char in unicodedata.normalize("NFC", text):
        if ord(char) < 128:
            result.append(char)
            continue
        base = "".join(c for c in unicodedata.normalize("NFKD", char) if not unicodedata.combining(c))
        if len(base) == 1 and base.isascii() and base.isalpha():
            result.append(base)
        else:
            result.append(char)
    return "".join(result)


def slugify(text):
    """Lowercase `text` and replace runs of non-alphanumeric characters with a single hyphen."""
    return re.sub(r"[^a-z0-9]+", "-", _transliterate_diacritics(text).lower()).strip("-")
import unittest

from toolkit.text import slugify, truncate


class TruncateTests(unittest.TestCase):
    def test_short_text_is_unchanged(self):
        self.assertEqual(truncate("abc", 5), "abc")

    def test_long_text_ends_in_ellipsis(self):
        self.assertEqual(truncate("abcdef", 4), "abc…")


class SlugifyTests(unittest.TestCase):
    def test_spaces_become_hyphens(self):
        self.assertEqual(slugify("Hello World"), "hello-world")

    def test_punctuation_collapses_to_single_hyphen(self):
        self.assertEqual(slugify("Hello, World!"), "hello-world")

    def test_leading_and_trailing_junk_is_stripped(self):
        self.assertEqual(slugify("  --Hello--  "), "hello")

    def test_already_a_slug_is_unchanged(self):
        self.assertEqual(slugify("already-a-slug"), "already-a-slug")

    def test_all_separator_input_becomes_empty_string(self):
        self.assertEqual(slugify("---"), "")

    def test_accented_vowel_mid_word_is_transliterated(self):
        self.assertEqual(slugify("café"), "cafe")

    def test_entirely_accented_word_is_not_empty(self):
        self.assertEqual(slugify("àéîõü"), "aeiou")

    def test_no_ascii_equivalent_mid_word_becomes_hyphen(self):
        self.assertEqual(slugify("aфb"), "a-b")

    def test_compatibility_symbol_mid_word_becomes_hyphen(self):
        self.assertEqual(slugify("aﬁb"), "a-b")

    def test_nfd_decomposed_accent_is_transliterated_like_precomposed(self):
        import unicodedata

        self.assertEqual(slugify(unicodedata.normalize("NFD", "cafés")), "cafes")
